SELECT (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name='t2') AS table_exists, (SELECT rootpage FROM sqlite_schema WHERE type='table' AND name='t2') AS rootpage, (SELECT group_concat(name, ',') FROM (SELECT name FROM pragma_table_info('t2') ORDER BY cid)) AS columns, (SELECT page_count FROM pragma_page_count) AS page_count, (SELECT freelist_count FROM pragma_freelist_count) AS freelist_count, (SELECT integrity_check FROM pragma_integrity_check LIMIT 1) AS integrity_check;